export const STYLES_CSS = ":root {\n  --bg: #0d1117;\n  --panel: #131922;\n  --panel-2: #182029;\n  --line: #232c38;\n  --fg: #c9d3df;\n  --dim: #7c8b9d;\n  --accent: #7aa2f7;\n  --ok: #7ac794;\n  --warn: #d6b16a;\n  --err: #e07a7a;\n  --mono: ui-monospace, SFMono-Regular, \"SF Mono\", Menlo, Consolas, monospace;\n}\n\n* { box-sizing: border-box; }\n\nbody {\n  margin: 0;\n  background: var(--bg);\n  color: var(--fg);\n  font: 13px/1.5 var(--mono);\n  height: 100vh;\n  display: grid;\n  grid-template-columns: 260px 1fr;\n}\n\nbutton, input, textarea, select {\n  font: inherit;\n  color: inherit;\n  background: var(--panel-2);\n  border: 1px solid var(--line);\n  border-radius: 4px;\n  padding: 4px 8px;\n}\n\nbutton { cursor: pointer; }\nbutton:hover { border-color: var(--accent); }\n\n/* ---- session rail ---- */\n\n#rail {\n  background: var(--panel);\n  border-right: 1px solid var(--line);\n  overflow-y: auto;\n  padding: 10px;\n}\n\n#rail h1 {\n  font-size: 12px;\n  letter-spacing: 0.14em;\n  text-transform: uppercase;\n  color: var(--dim);\n  margin: 4px 0 12px;\n}\n\n.session {\n  padding: 7px 8px;\n  border: 1px solid transparent;\n  border-radius: 4px;\n  cursor: pointer;\n  margin-bottom: 2px;\n}\n\n.session:hover { background: var(--panel-2); }\n.session.open { border-color: var(--accent); background: var(--panel-2); }\n.session .title { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.session .meta { color: var(--dim); font-size: 11px; }\n\n.status-running { color: var(--accent); }\n.status-dormant { color: var(--dim); }\n.status-ended { color: var(--err); }\n.status-idle { color: var(--ok); }\n\n/* ---- pane grid ---- */\n\n#grid {\n  display: grid;\n  gap: 1px;\n  background: var(--line);\n  overflow: hidden;\n  grid-template-columns: repeat(auto-fit, minmax(420px, 1fr));\n}\n\n#grid:empty::after {\n  content: \"select a session, or press N for a new one\";\n  color: var(--dim);\n  padding: 24px;\n}\n\n.pane {\n  background: var(--bg);\n  display: grid;\n  grid-template-rows: auto auto 1fr auto;\n  min-height: 0;\n  min-width: 0;\n}\n\n.pane-head {\n  display: flex;\n  gap: 8px;\n  align-items: center;\n  padding: 6px 10px;\n  background: var(--panel);\n  border-bottom: 1px solid var(--line);\n}\n\n.pane-head .title { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.pane-head .spacer { flex: 1; }\n.pane-search { padding: 4px 10px; border-bottom: 1px solid var(--line); background: var(--panel); }\n.pane-search input { width: 100%; }\n\n.transcript {\n  overflow-y: auto;\n  padding: 10px;\n  min-height: 0;\n}\n\n.entry { margin-bottom: 10px; white-space: pre-wrap; overflow-wrap: anywhere; }\n.entry.user { color: var(--accent); }\n.entry.user::before { content: \"> \"; }\n.entry.thinking { color: var(--dim); font-style: italic; }\n.entry.notice { color: var(--warn); }\n.entry mark { background: #3d4a2a; color: var(--fg); }\n\n.tool { border: 1px solid var(--line); border-radius: 4px; background: var(--panel); }\n.tool > summary { cursor: pointer; padding: 4px 8px; color: var(--dim); }\n.tool[data-status=\"running\"] > summary { color: var(--accent); }\n.tool[data-status=\"error\"] > summary { color: var(--err); }\n.tool .body { padding: 6px 8px; border-top: 1px solid var(--line); }\n.tool pre { margin: 0; white-space: pre-wrap; overflow-wrap: anywhere; color: var(--dim); }\n\n.diff { display: block; }\n.diff .del { color: var(--err); }\n.diff .ins { color: var(--ok); }\n\n.composer { display: flex; gap: 6px; padding: 8px; border-top: 1px solid var(--line); background: var(--panel); }\n.composer textarea { flex: 1; resize: none; height: 46px; }\n.queued { color: var(--warn); }\n";

export const APP_JS = "// The browser client. It imports the same reducer the TUI uses — /reduce.js is src/client/reduce.ts\n// with its types stripped — so the two front-ends cannot disagree about what a transcript means.\nimport { initialState, reduce } from \"/reduce.js\";\nimport { editDiff } from \"/diff.js\";\n\nconst railEl = document.getElementById(\"sessions\");\nconst gridEl = document.getElementById(\"grid\");\n\n/** sessionId -> { el, view, source, search, entryEls } */\nconst panes = new Map();\nlet sessions = [];\n\nasync function command(body) {\n  const response = await fetch(\"/api/command\", {\n    method: \"POST\",\n    headers: { \"content-type\": \"application/json\" },\n    body: JSON.stringify(body),\n  });\n  if (!response.ok) throw new Error(`${response.status}: ${await response.text()}`);\n  return (await response.json()).result;\n}\n\nasync function refreshSessions() {\n  sessions = await (await fetch(\"/api/sessions\")).json();\n  renderRail();\n}\n\nfunction renderRail() {\n  railEl.replaceChildren(\n    ...sessions.map((session) => {\n      const el = document.createElement(\"div\");\n      el.className = `session${panes.has(session.id) ? \" open\" : \"\"}`;\n      el.innerHTML =\n        `<span class=\"title\"></span><span class=\"meta status-${session.status}\"></span>`;\n      el.querySelector(\".title\").textContent = session.title || session.id;\n      el.querySelector(\".meta\").textContent = `${session.status} · ${session.backend}`;\n      el.onclick = () => (panes.has(session.id) ? closePane(session.id) : openPane(session.id));\n      return el;\n    }),\n  );\n}\n\nfunction openPane(sessionId) {\n  if (panes.has(sessionId)) return;\n\n  const el = document.createElement(\"section\");\n  el.className = \"pane\";\n  el.innerHTML = `\n    <div class=\"pane-head\">\n      <span class=\"title\"></span>\n      <select class=\"models\" title=\"model\"></select>\n      <span class=\"state\"></span>\n      <button class=\"abort\">abort</button>\n      <button class=\"close\">×</button>\n    </div>\n    <div class=\"pane-search\"><input placeholder=\"filter transcript\" /></div>\n    <div class=\"transcript\"></div>\n    <form class=\"composer\">\n      <textarea placeholder=\"message — enter to send, shift+enter for a newline\"></textarea>\n      <button type=\"submit\">send</button>\n    </form>`;\n\n  const pane = { el, view: initialState(), source: undefined, search: \"\", entryEls: new Map(), sessionId };\n  panes.set(sessionId, pane);\n  gridEl.append(el);\n\n  el.querySelector(\".close\").onclick = () => closePane(sessionId);\n  el.querySelector(\".abort\").onclick = () => command({ type: \"abort\", sessionId });\n  el.querySelector(\".pane-search input\").oninput = (event) => {\n    pane.search = event.target.value.toLowerCase();\n    pane.entryEls.clear();\n    renderPane(pane);\n  };\n  el.querySelector(\".models\").onchange = (event) =>\n    command({ type: \"set_model\", sessionId, modelId: event.target.value });\n\n  const composer = el.querySelector(\".composer\");\n  const textarea = composer.querySelector(\"textarea\");\n  composer.onsubmit = (event) => {\n    event.preventDefault();\n    send(pane, textarea);\n  };\n  textarea.onkeydown = (event) => {\n    if (event.key === \"Enter\" && !event.shiftKey) {\n      event.preventDefault();\n      send(pane, textarea);\n    }\n  };\n\n  // Cookie auth: EventSource cannot set an Authorization header, which is why the host offers the\n  // one-time /auth handoff that turns a token into an HttpOnly cookie.\n  pane.source = new EventSource(`/api/sessions/${encodeURIComponent(sessionId)}/events?since=0`);\n  pane.source.onmessage = (event) => {\n    pane.view = reduce(pane.view, JSON.parse(event.data));\n    renderPane(pane);\n  };\n\n  renderRail();\n  renderPane(pane);\n}\n\nfunction closePane(sessionId) {\n  const pane = panes.get(sessionId);\n  if (!pane) return;\n  pane.source?.close();\n  pane.el.remove();\n  panes.delete(sessionId);\n  renderRail();\n}\n\nasync function send(pane, textarea) {\n  const text = textarea.value.trim();\n  if (!text) return;\n  textarea.value = \"\";\n  // Typing while the agent works queues rather than interrupts; steering is a deliberate act.\n  const when = pane.view.status === \"running\" ? \"after_turn\" : \"now\";\n  await command({ type: \"send\", sessionId: pane.sessionId, text, when });\n}\n\nfunction renderPane(pane) {\n  const { view, el } = pane;\n  const summary = sessions.find((session) => session.id === pane.sessionId);\n  el.querySelector(\".title\").textContent = summary?.title ?? pane.sessionId;\n\n  const queued = view.queue.length > 0 ? ` · ${view.queue.length} queued` : \"\";\n  const state = el.querySelector(\".state\");\n  state.textContent = `${view.status}${queued}${contextLabel(view)}`;\n  state.className = `state status-${view.status}${view.queue.length ? \" queued\" : \"\"}`;\n\n  renderModels(el.querySelector(\".models\"), view);\n  renderTranscript(pane);\n}\n\nfunction contextLabel(view) {\n  if (!view.contextUsage) return \"\";\n  const { used, window } = view.contextUsage;\n  return window > 0 ? ` · ${Math.round((used / window) * 100)}% context` : ` · ${used} tokens`;\n}\n\n/** Grouped by provider: Claude offers one group, pi offers dozens. Same control either way. */\nfunction renderModels(select, view) {\n  const models = view.capabilities?.models ?? [];\n  if (select.dataset.count === String(models.length)) {\n    if (view.model) select.value = view.model.id;\n    return;\n  }\n  select.dataset.count = String(models.length);\n  select.replaceChildren();\n\n  const byProvider = new Map();\n  for (const model of models) {\n    const provider = model.provider ?? \"other\";\n    byProvider.set(provider, [...(byProvider.get(provider) ?? []), model]);\n  }\n  for (const [provider, group] of [...byProvider].sort(([a], [b]) => a.localeCompare(b))) {\n    const optgroup = document.createElement(\"optgroup\");\n    optgroup.label = provider;\n    for (const model of group) {\n      const option = document.createElement(\"option\");\n      option.value = model.id;\n      option.textContent = model.label ?? model.id;\n      optgroup.append(option);\n    }\n    select.append(optgroup);\n  }\n  if (view.model) select.value = view.model.id;\n}\n\n/**\n * Keyed reconciliation rather than a full rebuild: assistant text arrives as snapshots that grow\n * with every delta, and rebuilding the transcript on each one would fight the user's scrolling.\n */\nfunction renderTranscript(pane) {\n  const container = pane.el.querySelector(\".transcript\");\n  const atBottom = container.scrollHeight - container.scrollTop - container.clientHeight < 40;\n\n  const visible = pane.view.entries.filter((entry) => matches(entry, pane.search));\n  const seen = new Set();\n\n  for (const entry of visible) {\n    const key = `${entry.kind}:${entry.id}`;\n    seen.add(key);\n    let el = pane.entryEls.get(key);\n    if (!el) {\n      el = document.createElement(\"div\");\n      pane.entryEls.set(key, el);\n      container.append(el);\n    }\n    updateEntry(el, entry, pane.search);\n  }\n\n  for (const [key, el] of pane.entryEls) {\n    if (!seen.has(key)) {\n      el.remove();\n      pane.entryEls.delete(key);\n    }\n  }\n\n  if (atBottom) container.scrollTop = container.scrollHeight;\n}\n\nfunction matches(entry, search) {\n  if (!search) return true;\n  const haystack = entry.kind === \"tool\" ? `${entry.name} ${stringify(entry.result)}` : entry.text;\n  return (haystack ?? \"\").toLowerCase().includes(search);\n}\n\nfunction updateEntry(el, entry, search) {\n  if (entry.kind === \"tool\") {\n    el.className = \"entry\";\n    renderTool(el, entry);\n    return;\n  }\n  el.className = `entry ${entry.kind}`;\n  el.replaceChildren(...highlight(entry.text, search));\n}\n\nfunction renderTool(el, entry) {\n  let details = el.firstElementChild;\n  if (!details) {\n    details = document.createElement(\"details\");\n    details.className = \"tool\";\n    details.innerHTML = `<summary></summary><div class=\"body\"></div>`;\n    el.append(details);\n  }\n  details.dataset.status = entry.status;\n  details.querySelector(\"summary\").textContent = `${entry.name} · ${entry.status}`;\n\n  const body = details.querySelector(\".body\");\n  const diff = diffFor(entry);\n  if (diff) {\n    body.replaceChildren(diff);\n    return;\n  }\n  const pre = document.createElement(\"pre\");\n  pre.textContent = `${stringify(entry.input)}\\n\\n${stringify(entry.result) ?? \"\"}`.trim();\n  body.replaceChildren(pre);\n}\n\n/** File edits are the tool output people actually read, so show them as a diff, not as JSON. */\nfunction diffFor(entry) {\n  const diff = editDiff(entry.input);\n  if (!diff) return undefined;\n\n  const wrapper = document.createElement(\"pre\");\n  wrapper.className = \"diff\";\n  if (diff.path) {\n    const path = document.createElement(\"div\");\n    path.textContent = diff.path;\n    wrapper.append(path);\n  }\n  for (const line of diff.removed) wrapper.append(line_(\"del\", `- ${line}`));\n  for (const line of diff.added) wrapper.append(line_(\"ins\", `+ ${line}`));\n  return wrapper;\n}\n\nfunction line_(className, text) {\n  const el = document.createElement(\"div\");\n  el.className = className;\n  el.textContent = text;\n  return el;\n}\n\nfunction highlight(text, search) {\n  if (!search) return [document.createTextNode(text ?? \"\")];\n  const nodes = [];\n  const haystack = text ?? \"\";\n  let index = 0;\n  for (;;) {\n    const at = haystack.toLowerCase().indexOf(search, index);\n    if (at === -1) break;\n    if (at > index) nodes.push(document.createTextNode(haystack.slice(index, at)));\n    const mark = document.createElement(\"mark\");\n    mark.textContent = haystack.slice(at, at + search.length);\n    nodes.push(mark);\n    index = at + search.length;\n  }\n  nodes.push(document.createTextNode(haystack.slice(index)));\n  return nodes;\n}\n\nfunction stringify(value) {\n  if (value === undefined || value === null) return undefined;\n  if (typeof value === \"string\") return value;\n  try {\n    return JSON.stringify(value, null, 2);\n  } catch {\n    return String(value);\n  }\n}\n\nlet config = { scope: \".\", backends: [\"claude\"] };\n\ndocument.getElementById(\"new-session\").onclick = async () => {\n  const id = await command({ type: \"create\", scope: config.scope, backend: config.backends[0] });\n  await refreshSessions();\n  openPane(id);\n};\n\ndocument.addEventListener(\"keydown\", (event) => {\n  if (event.key === \"n\" && event.target === document.body) {\n    document.getElementById(\"new-session\").click();\n  }\n});\n\nconfig = await (await fetch(\"/api/config\")).json();\nawait refreshSessions();\nsetInterval(() => void refreshSessions(), 2000);\nfor (const session of sessions.slice(0, 1)) openPane(session.id);\n";

export const REDUCER_JS = "                                                                                                           \n                                                             \n\n/**\n * The reducer both front-ends share. The TUI and the web UI import this same function, which is\n * what stops them drifting.\n *\n * Pure and order-dependent only on `seq`: replaying a Presentation Transcript twice gives the same\n * state, and a client joining at `since: N` converges with one that saw everything.\n */\n\n                                                          \n\n                   \n                                              \n                                                                   \n                                                                  \n                                                                                                                      \n                                                                     \n\n                         \n                        \n                   \n                 \n                              \n                    \n                   \n                  \n                                                  \n                       \n                  \n  \n\nexport function initialState()            {\n  return { status: \"idle\", entries: [], queue: [], lastSeq: 0 };\n}\n\nexport function reduceAll(entries                       , from            = initialState())            {\n  let state = from;\n  for (const entry of entries) state = reduce(state, entry);\n  return state;\n}\n\nexport function reduce(state           , entry             )            {\n  const next = applyEvent(state, entry.event);\n  return next === state ? state : { ...next, lastSeq: entry.seq };\n}\n\nfunction applyEvent(state           , event            )            {\n  switch (event.type) {\n    case \"session_started\":\n      return { ...state, backend: event.backend, scope: event.scope, capabilities: event.capabilities };\n\n    case \"capabilities_changed\":\n      return { ...state, capabilities: event.capabilities };\n\n    case \"user_message\":\n      return { ...state, entries: upsert(state.entries, { kind: \"user\", id: event.id, text: event.text }) };\n\n    case \"turn_started\":\n      return { ...state, status: \"running\" };\n\n    case \"message\":\n      return {\n        ...state,\n        entries: upsert(state.entries, { kind: \"assistant\", id: event.id, text: event.text, final: event.final }),\n      };\n\n    case \"thinking\":\n      return {\n        ...state,\n        entries: upsert(state.entries, { kind: \"thinking\", id: event.id, text: event.text, final: event.final }),\n      };\n\n    case \"tool_started\":\n      return {\n        ...state,\n        entries: upsert(state.entries, {\n          kind: \"tool\",\n          id: event.callId,\n          name: event.name,\n          input: event.input,\n          status: \"running\",\n        }),\n      };\n\n    case \"tool_updated\":\n      return { ...state, entries: patchTool(state.entries, event.callId, (tool) => ({ ...tool, update: event.update })) };\n\n    case \"tool_ended\":\n      return {\n        ...state,\n        entries: patchTool(state.entries, event.callId, (tool) => ({\n          ...tool,\n          result: event.result,\n          status: event.isError ? \"error\" : \"complete\",\n        })),\n      };\n\n    case \"turn_ended\":\n      return { ...state, status: \"idle\" };\n\n    case \"queue_changed\":\n      return { ...state, queue: [...event.pending] };\n\n    case \"context_usage\":\n      return { ...state, contextUsage: { used: event.used, window: event.window } };\n\n    case \"model_changed\":\n      return { ...state, model: event.model };\n\n    case \"notice\":\n      return {\n        ...state,\n        entries: [...state.entries, { kind: \"notice\", id: `notice-${state.entries.length}`, level: event.level, text: event.text }],\n      };\n\n    case \"session_dormant\":\n      return {\n        ...state,\n        status: \"dormant\",\n        queue: [],\n        entries: [\n          ...state.entries,\n          { kind: \"notice\", id: `dormant-${state.entries.length}`, level: \"info\", text: `Dormant: ${event.reason}` },\n        ],\n      };\n\n    case \"revived\":\n      return {\n        ...state,\n        status: \"idle\",\n        entries: [\n          ...state.entries,\n          { kind: \"notice\", id: `revived-${event.fromSeq}`, level: \"info\", text: `Revived from seq ${event.fromSeq}` },\n        ],\n      };\n\n    case \"session_ended\":\n      return { ...state, status: \"ended\", endedReason: event.reason };\n  }\n}\n\n/** Upsert by id — the snapshot semantics the event union is built on. */\nfunction upsert(entries         , entry       )          {\n  const index = entries.findIndex((candidate) => candidate.kind === entry.kind && candidate.id === entry.id);\n  if (index < 0) return [...entries, entry];\n  const copy = [...entries];\n  copy[index] = entry;\n  return copy;\n}\n\nfunction patchTool(\n  entries         ,\n  callId        ,\n  patch                                                   ,\n)          {\n  const index = entries.findIndex((candidate) => candidate.kind === \"tool\" && candidate.id === callId);\n  if (index < 0) return entries;\n  const existing = entries[index];\n  if (!existing || existing.kind !== \"tool\") return entries;\n  const copy = [...entries];\n  copy[index] = patch(existing);\n  return copy;\n}\n";

export const DIFF_JS = "/**\n * Turning a file-editing tool call into something readable.\n *\n * Shared with the browser the same way the reducer is: types only, so stripping leaves standalone\n * ESM. Kept out of the DOM so it can be tested directly.\n */\n\n                        \n                \n                    \n                  \n  \n\n/**\n * Recognises the file-editing tools whose output people actually read. Claude's Edit carries\n * `old_string`/`new_string`; Write carries `content` with nothing removed.\n */\nexport function editDiff(input         )                       {\n  if (!input || typeof input !== \"object\") return undefined;\n  const record = input                           ;\n\n  const before = typeof record[\"old_string\"] === \"string\" ? record[\"old_string\"] : undefined;\n  const after =\n    typeof record[\"new_string\"] === \"string\"\n      ? record[\"new_string\"]\n      : typeof record[\"content\"] === \"string\"\n        ? record[\"content\"]\n        : undefined;\n\n  if (before === undefined && after === undefined) return undefined;\n\n  return {\n    ...(typeof record[\"file_path\"] === \"string\" ? { path: record[\"file_path\"] } : {}),\n    removed: lines(before),\n    added: lines(after),\n  };\n}\n\nfunction lines(text                    )           {\n  if (!text) return [];\n  const split = text.split(\"\\n\");\n  while (split.length > 0 && split[split.length - 1] === \"\") split.pop();\n  return split;\n}\n";
